import pandas as pd
from collections import Counter

def task_func(obj_list, attribute):
    # Return an empty DataFrame with the expected columns if no objects are provided.
    if not obj_list:
        return pd.DataFrame(columns=['attribute', 'count'])

    # Count the occurrences of the given attribute value in the object list.
    counts = Counter(getattr(obj, attribute) for obj in obj_list)

    # Build a DataFrame from the counter.
    df = pd.DataFrame({
        'attribute': list(counts.keys()),
        'count': list(counts.values())
    })

    return df

import numpy as np
import pandas as pd

def task_func(arr):
    # Find minimum and maximum of the array
    min_val = arr.min()
    max_val = arr.max()

    # If all values are the same, return zeros
    if max_val == min_val:
        scaled_values = np.zeros_like(arr, dtype=float)
    else:
        scaled_values = (arr - min_val) / (max_val - min_val)

    # Return the result as a DataFrame with the required column name
    return pd.DataFrame({'Scaled Values': scaled_values})
